namespace ghidra.framework.main.datatree;










using docking;
using docking;
using docking.widgets.table;
using docking.widgets.table.threaded;
using docking.widgets.table.threaded;
using ghidra.framework.main.datatable;
using ghidra.framework.model;
using ghidra.framework.model;
using ghidra.framework.plugintool;
using ghidra.util;

/**
 * Dialog that shows all checkouts in a specific folder and all of its subfolders.
 *
 */
public class FindCheckoutsDialog : DialogComponentProvider {

	private FindCheckoutsTableModel model;
	private Plugin plugin;
	private DomainFolder folder;
	private GTable table;
	private bool showMessage = true;
	private GThreadedTablePanel<CheckoutInfo> threadedTablePanel;

	public FindCheckoutsDialog(Plugin plugin, DomainFolder folder) : base("Find Checkouts")
    {
		this.plugin = plugin;
		this.folder = folder;
		create();
		setHelpLocation(new HelpLocation("VersionControl", "Find_Checkouts"));
	}

	private void create() {

		model = new FindCheckoutsTableModel(folder, plugin.getTool());
		model.addInitialLoadListener(new _Anon_ThreadedTableModelListener_1());

		threadedTablePanel = new(model);
		table = threadedTablePanel.getTable();

		TableColumnModel columnModel = table.getColumnModel();
		MyCellRenderer cellRenderer = new MyCellRenderer();

		for (int i = 0; i < columnModel.getColumnCount(); i++) {
			TableColumn column = columnModel.getColumn(i);
			column.setCellRenderer(cellRenderer);
			string name = (string) column.getIdentifier();
			if (name.equals(FindCheckoutsTableModel.CHECKOUT_DATE)) {
				column.setPreferredWidth(180);
			}
		}

		table.setPreferredScrollableViewportSize(
			new Dimension(threadedTablePanel.getPreferredSize().width, 150));
		threadedTablePanel.getAccessibleContext().setAccessibleName("Find Checkouts");
		addWorkPanel(threadedTablePanel);
		addDismissButton();
	}

	private List<DomainFile> getFileList() {
		List<DomainFile> list = new();
		int[] selectedRows = table.getSelectedRows();
		foreach (int selectedRow in selectedRows) {
			list.add(model.getDomainFile(selectedRow));
		}
		return list;
	}

	/* @Override */
	public void close() {
		base.close();
		threadedTablePanel.dispose();
	}

	/* @Override */
	public ActionContext getActionContext(MouseEvent @event) {
		return new ProjectDataContext(null, folder.getProjectData(), null, null, getFileList(),
			null, true);
	}

	private class MyCellRenderer : GTableCellRenderer {

		/* @Override */
		public Component getTableCellRendererComponent(GTableCellRenderingData data) {

			base.getTableCellRendererComponent(data);

			object value = data.getValue();

			if (value is Date) {
				setText(DateUtils.formatDateTimestamp((Date) value));
			}

			setBorder(BorderFactory.createEmptyBorder(0, 5, 0, 0));

			string toolTipText = null;

			int col = data.getColumnModelIndex();
			if (col == CheckoutsTableModel.DATE_COL) {
				toolTipText = "Date when file was checked out";
			}
			setToolTipText(toolTipText);
			return this;
		}
	}

	internal class _Anon_ThreadedTableModelListener_1 : ThreadedTableModelListener
	{


			/* @Override */
			public void loadPending() {
				// don't care
			}

			/* @Override */
			public void loadingStarted() {
				// don't care
			}

			/* @Override */
			public void loadingFinished(bool wasCancelled) {
				if (wasCancelled) {
					setStatusText("Find Checkouts Cancelled");
					return;
				}

				bool hasData = model.getRowCount() > 0;
				if (!hasData && showMessage) {
					Msg.showInfo(getClass(), threadedTablePanel, "Find Checkouts",
						"No checkouts were found.");
					this.close();
				}
			}
		
	}

}
